let lang=params.get('lang')==='fr'?'fr':'en',session=null,events=null,state=onPhone?'intro':'qr',stream=null,results=null,selected=0,stage=0,message='',tilt=null,photo=null,checking=false,stable=0,counting=false;
const en={title:"Let's find your perfect size",recommended:'Your recommended size',product:'Photo-based size estimate',intro:'Take a photo of your hand with a standard-size card.',examples:'See examples',private:'Photos are processed on this device. Only measurements sync to your PC.',start:'Start now',qrTitle:'Find your perfect size for this ring with our AI Virtual Sizer',qrText:'Scan the QR and follow the steps, it takes less than 2 minutes.',continue:'Continue on this device',connected:'Phone connected',connectedText:'Follow the steps on your phone. Your measurements will appear here automatically.',calculating:'We are calculating your size…',time:'Detecting your hand and card, then measuring each finger.',steps:['Detect the hand and card','Measure the proportions','Calculate the size'],little:'Little finger',ring:'Ring finger',middle:'Middle finger',index:'Index finger',fit:'Estimated fit',description:'Estimated from the visible width of your finger, calibrated against the card in your photo.',quality:'Image measurement quality — not probability of fit',repeat:'Repeat measurement',estimate:'Experimental independent estimate. Finger depth is inferred from a single photo. Confirm with a physical sizing kit before ordering.',card:'Card',hand:'Hand',checks:['Keep hand and card visible; fill the frame','Spread your fingers','Lay your phone flat'],upload:'Choose photo',shutter:'Take photo',hold:'Perfect. Stay still!',cameraError:'Camera unavailable or permission declined. Choose a photo of your hand and card instead.',modelLoading:'Loading the local hand model…',privacy:'privacy policy',terms:'measurement guide',legal:'Read our',and:'and',retry:'Try again',back:'Back',noResult:'We could not measure this photo',phoneError:'The photo needs another attempt. Follow the message on your phone.',cardsTitle:'Some examples of valid cards',cards:['Blank standard card','Loyalty card','Membership card','Hotel key card','Gift card','Public transport card'],close:'Close',privacyText:'The hand photo is analysed locally in your browser using downloaded computer-vision models. It is not sent to Aitaca, Google or a server. Only finger measurements are shared with the paired PC through a temporary session. Session results are kept in server memory for two hours. Camera access stops after capture.',guideText:'Place a standard 85.60 × 53.98 mm card above your spread hand, on the same flat surface. Use a plain contrasting background, even lighting and a photo directly from above. Cover private card details without covering its edges. This experimental estimator infers finger depth; image quality is not a validated probability that a ring will fit.',out:'Outside the guide range; do not use this size for ordering.',loading:'Starting your sizing session…',expired:'The session expired. Reload the PC page and scan its new QR.'};
