Object.assign(en,{loose:'Loose fit',ok:'OK fit',tight:'Tight fit',unavailable:'No matching size',circumference:'Estimated circumference',looseDescription:'Your circumference falls in the Loose zone for this product size.',okDescription:'Your circumference falls in the OK zone for this product size.',tightDescription:'Your circumference falls in the Tight zone for this product size.',out:'Below 50.6 mm: no size in your product table matches this circumference.'});
