en.privacyText='Camera frames and captured photos travel through ngrok to your PC. Local test recording is enabled at your request: images, errors and results are saved in a private test folder on this PC for debugging until removed. No external AI service receives them.';
fr.privacyText='Les images transitent par ngrok vers votre PC. À votre demande, le mode test conserve les images, erreurs et résultats dans un dossier privé sur ce PC pour le diagnostic, jusqu’à leur suppression. Aucun service IA externe ne les reçoit.';
const t=k=>(lang==='fr'?fr:en)[k];
const handPath='M19 81 15 27Q14 20 18 20Q21 20 22 27L26 46Q28 49 29 44L26 12Q25 6 29 6Q33 6 33 12L36 43Q38 46 40 41L40 7Q40 1 44 1Q48 1 48 7L47 43Q49 48 52 43L56 15Q57 9 61 10Q64 11 63 17L60 52Q60 63 65 58L72 44Q75 39 79 42Q82 45 77 53L66 71 59 82';
function handIcon(index=0){const markers=[[18,45,25,44],[28,44,36,43],[39,44,47,45],[53,47,61,49]],m=markers[index];return `<svg viewBox="0 0 90 90" aria-hidden="true"><path d="${handPath}" fill="none" stroke="#536175" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M${m[0]} ${m[1]} ${m[2]} ${m[3]}" fill="none" stroke="#f84583" stroke-width="8" stroke-linecap="round"/></svg>`;}
let testPercent=0;
function adjustedResult(result){return resultWithAdjustedTable(result,testPercent);}
function adjustedOutDescription(result){
 const rows=adjustedFitTable(fingerTablePercent(result.finger,testPercent)),format=n=>n.toLocaleString(lang==='fr'?'fr-FR':'en-US',{maximumFractionDigits:6});
 const min=format(rows[0].min),max=format(rows.at(-1).maxInclusive);
 return lang==='fr'?`Nous n’avons pas encore cette taille. La circonférence mesurée est hors de notre plage disponible (${min} à ${max} mm). Elle reste affichée ci-dessous, sans taille attribuée.`:`We don’t have that size yet. The measured circumference is outside our available range (${min} to ${max} mm). It is still shown below, with no size assigned.`;
}
function testAdjustMarkup(result){
 if(result.finger!=='little')return '';
 const fr=lang==='fr';
 return `<div class="confirmed-size-panel"><label for="test-percent">${fr?'Ajuster les seuils du tableau — auriculaire uniquement':'Adjust table thresholds — little finger only'}</label><select id="test-percent">${[-4,-3,-2,-1,0,1,2,3,4].map(p=>`<option value="${p}" ${testPercent===p?'selected':''}>${p===0?(fr?'Aucun ajustement':'No adjustment'):(p>0?'+':'−')+Math.abs(p)+' %'}</option>`).join('')}</select><p>${fr?'Applique ce pourcentage aux seuils du tableau pour l’auriculaire uniquement. Les autres doigts utilisent le tableau original. La circonférence et la qualité restent inchangées.':'Applies this percentage to table thresholds for the little finger only. Other fingers use the original table. Circumference and quality stay unchanged.'}</p></div>`;
}
function testTableMarkup(result){
 const appliedPercent=fingerTablePercent(result.finger,testPercent);
 const fr=lang==='fr',format=n=>n.toLocaleString(fr?'fr-FR':'en-US',{maximumFractionDigits:6});
 const percent=appliedPercent>0?'+'+appliedPercent:String(appliedPercent);
 return `<section class="test-sizing-table" aria-label="${fr?'Tableau de test des tailles':'Test sizing table'}"><h2>${fr?'Tableau des tailles pour test':'Sizing table for testing'} (${percent} %)</h2><p>${fr?'C = circonférence en mm. Seuils utilisés pour le résultat affiché.':'C = circumference in mm. Thresholds used for the displayed result.'}</p><div class="test-table-scroll" tabindex="0" role="region" aria-label="${fr?'Tableau des seuils ajustés':'Adjusted threshold table'}"><table><thead><tr><th scope="col">${fr?'Taille':'Size'}</th><th scope="col">${fr?'Ample':'Loose'}</th><th scope="col">OK</th><th scope="col">${fr?'Serré':'Tight'}</th></tr></thead><tbody>${adjustedFitTable(appliedPercent).map(row=>{
 const chosen=result.measured!==false&&!result.outOfRange&&result.size===row.size;
 const cell=(zone,text)=>`<td${chosen&&result.zone===zone?' class="active-fit"':''}>${text}${chosen&&result.zone===zone?`<span class="test-table-match">${fr?'Résultat actuel':'Current result'}</span>`:''}</td>`;
 return `<tr${chosen?' class="active-size"':''}><th scope="row">US ${row.size}</th>${cell('loose',`${format(row.min)} ≤ C &lt; ${format(row.okMin)}`)}${cell('ok',`${format(row.okMin)} ≤ C ≤ ${format(row.okMax)}`)}${cell('tight',row.maxEx===null?'—':`${format(row.okMax)} &lt; C &lt; ${format(row.maxEx)}`)}</tr>`;
 }).join('')}</tbody></table></div><p>${fr?'Tailles disponibles pour C de':'Sizes available for C from'} ${format(adjustedFitTable(appliedPercent)[0].min)} ${fr?'à':'to'} ${format(adjustedFitTable(appliedPercent).at(-1).maxInclusive)} mm (${fr?'limites incluses':'inclusive'}).</p></section>`;
}
function tableSizeMarkup(result){
 return `<p class="table-size-reference">${lang==='fr'?'Taille selon votre tableau':'Size from your sizing table'} : <strong>${result.measured===false||result.outOfRange?'—':'US '+result.size}</strong>${result.measured===false||result.outOfRange?'':' · '+t(result.zone)}</p>`;
}
function fingerFailureDescription(result){
 const fr=lang==='fr';
 const reasons={
 'inconsistent-widths':fr?'Les largeurs relevées sur ce doigt sont trop différentes pour calculer une circonférence fiable. Reprenez la photo avec le doigt à plat, la caméra directement au-dessus et sans bouger.':'The widths measured across this finger disagree too much to calculate a reliable circumference. Retake the photo with the finger flat, the camera directly above it and no movement.',
 'hand-outline-unavailable':fr?'Le contour de la main n’a pas pu être séparé du fond. Utilisez un fond uni contrasté, un éclairage uniforme et gardez toute la main visible.':'The hand outline could not be separated from the background. Use a plain contrasting background, even lighting and keep the whole hand visible.',
 'finger-edges-unavailable':fr?'Les deux bords de ce doigt n’ont pas pu être suivis sur suffisamment de lignes à l’endroit de la bague. Écartez les doigts, gardez-les entièrement visibles et évitez les ombres sur leurs bords.':'Both edges of this finger could not be followed across enough measurement lines at the ring position. Separate your fingers, keep them fully visible and avoid shadows along the edges.'
 };
 return (reasons[result.failureReason]||(fr?'Aucune largeur exploitable n’a pu être obtenue pour ce doigt. Reprenez une photo nette de la main entière, avec les doigts séparés et la carte visible.':'No usable width could be obtained for this finger. Retake a sharp photo of the whole hand with separated fingers and the reference card visible.'))+' '+(fr?'Circonférence indisponible : aucune valeur fiable à afficher.':'Circumference unavailable: no reliable value to display.');
}
function stabilityNotice(result){
if(!result.stability?.checked||result.stability.stable!==false||result.measured===false)return '';
return `<p class="stability-notice" role="status">${lang==='fr'?'Estimation instable : la mesure change lors de la vérification de la photo. Reprenez la photo avant de choisir une taille.':'Unstable estimate: the measurement changes when the photo is checked. Retake the photo before choosing a size.'}</p>`;
}
function circumferenceCalculation(result){
if(result.measured===false||!Number.isFinite(result.widthMm))return '';
const french=lang==='fr',label=french?'Calcul de la circonférence':'Circumference calculation';
const format=value=>value.toLocaleString(french?'fr-FR':'en-US',{minimumFractionDigits:2,maximumFractionDigits:4});
if(result.calibrationId)return `<div class="circumference-calculation"><strong>${label}</strong><p>${french?'Largeur mesurée':'Measured width'} : ${format(result.widthMm)} mm</p><p>${french?'Circonférence calculée avec le modèle calibré':'Circumference calculated with the calibrated model'} : ${format(result.circumference)} mm</p></div>`;
const photoCircumference=result.measurementSource==='measured'?result.photoCircumference:result.circumference;
if(!Number.isFinite(photoCircumference))return '';
const width=photoCircumference/Math.PI;
return `<div class="circumference-calculation"><strong>${label}${result.measurementSource==='measured'?(french?' de la photo':' from the photo'):''}</strong><p>${french?'Largeur':'Width'} × π ≈ ${format(width)} mm × ${french?'3,14159':'3.14159'}</p><p><b>${french?'Circonférence estimée':'Estimated circumference'} ≈ ${format(photoCircumference)} mm</b></p><small>${french?'Valeurs affichées arrondies ; calcul réalisé avec la précision complète.':'Displayed values are rounded; calculation uses full precision.'}</small></div>`;
}
function processingIcon(){return `<svg viewBox="0 0 130 170" fill="none" aria-hidden="true"><rect x="45" y="2" width="39" height="25" rx="2" stroke="#a3a3a3"/><g transform="translate(20 35)"><path d="${handPath}" stroke="#999" stroke-width="1.6"/></g><path d="m102 45 3 9 9 3-9 3-3 9-3-9-9-3 9-3 3-9Zm-75 64 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6Z" stroke="#ce04a5" stroke-width="2"/></svg>`;}
let countdownVersion=0,liveReady=false,level=null,orientationRequest=null;
function cancelCountdown(){countdownVersion++;counting=false;stable=0;document.querySelector('#countdown')?.classList.add('hidden');document.querySelector('#capture-ready')?.classList.add('hidden');document.querySelector('.capture-checks')?.classList.remove('hidden');}
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;liveReady=false;cancelCountdown();}
async function requestOrientation(){if(orientationRequest)return orientationRequest;const api=window.DeviceOrientationEvent;if(typeof api?.requestPermission==='function'){orientationRequest=api.requestPermission().catch(()=> 'denied');return orientationRequest;}return 'granted';}
function updateLevel(){if(state==='capture')drawCameraLevel(level);}
async function countdownCapture(){counting=true;const version=++countdownVersion,node=document.querySelector('#countdown');node.classList.remove('hidden');document.querySelector('.capture-checks').classList.add('hidden');document.querySelector('#capture-ready').classList.remove('hidden');const started=performance.now();while(performance.now()-started<3000){if(version!==countdownVersion)return;if(state!=='capture'||!stream||!liveReady||(tilt!==null&&tilt>=10)){cancelCountdown();return;}node.textContent=Math.max(1,Math.ceil((3000-(performance.now()-started))/1000));await new Promise(r=>setTimeout(r,100));}if(version===countdownVersion&&state==='capture'&&stream&&liveReady)document.querySelector('#shutter').click();}

function button(id,key,outline=false){return `<button class="scan-button${outline?' outline':''}" id="${id}">${t(key)}</button>`;}
function legal(){return `<p class="scan-legal">${t('legal')} <button data-policy="privacy">${t('privacy')}</button> ${t('and')} <button data-policy="terms">${t('terms')}</button>.</p>`;}
function modal(title,body){const m=document.querySelector('#policy');m.className='scan-modal';m.querySelector('h2').textContent=title;m.querySelector('div').innerHTML=body;m.querySelector('.dismiss').textContent=t('close');m.showModal();}
document.querySelectorAll('#policy .close,#policy .dismiss').forEach(b=>b.onclick=()=>document.querySelector('#policy').close());
async function patch(data){const r=await fetch(`/api/sessions/${session.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw new Error(t('expired'));return r.json();}
function render(){document.body.classList.toggle('camera-active',state==='capture');document.documentElement.lang=lang;document.title=t('title');
if(state==='closed'){
app.innerHTML=`<section class="scan-status"><h1>${lang==='fr'?'Session fermée':'Session closed'}</h1><p>${lang==='fr'?'La page PC a été réinitialisée. Scannez le nouveau QR code sur le PC pour recommencer. Vous pouvez fermer cet onglet.':'The PC page was reset. Scan the new QR code on the PC to start again. You can close this tab.'}</p></section>`;
}else if(state==='qr'){
app.innerHTML=`<section class="scan-shell qr-entry"><button class="scan-lang" id="language">${lang==='en'?'FR':'EN'}</button><h1>${t('title')}</h1><div class="qr-panel"><h2>${t('qrTitle')}</h2><p>${t('qrText')}</p><div class="qr-code" id="qr"></div></div>${legal()}<button class="scan-link" id="this-device">${t('continue')}</button></section>`;
if(session){const url=new URL(location.href);url.search='';url.searchParams.set('scan','1');url.searchParams.set('sid',session.id);url.searchParams.set('lang',lang);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();document.querySelector('#qr').innerHTML=qr.createSvgTag({cellSize:4,margin:0,scalable:true});}
document.querySelector('#this-device').onclick=()=>{state='intro';render();};document.querySelector('#language').onclick=()=>{lang=lang==='en'?'fr':'en';render();};
}else if(state==='intro'){
app.innerHTML=`<section class="scan-intro"><img src="assets/onboarding_camera_img.svg" alt="${t('intro')}"><div class="intro-copy"><h1>${t('intro')}</h1><button class="example-button" id="examples">${t('examples')}</button><div class="scan-privacy"><span>♙</span><span>${t('private')}</span></div>${button('start','start')}</div></section>`;
document.querySelector('#examples').onclick=()=>modal(t('cardsTitle'),`<div class="examples-grid">${t('cards').map(card=>`<span>• ${card}</span>`).join('')}</div>`);document.querySelector('#start').onclick=async()=>{requestOrientation();state='capture';render();patch({status:'capturing',results:null}).catch(()=>{});startCamera();};
}else if(state==='capture'){
beginCaptureTest();
app.innerHTML=captureMarkup(t,handPath);
document.querySelector('#back').onclick=()=>{stop();state='intro';render();};document.querySelector('#upload').onclick=()=>document.querySelector('#photo-file').click();document.querySelector('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{photo=await createImageBitmap(file);await measure();}catch(err){showError(err.message);}};document.querySelector('#shutter').onclick=async()=>{const video=document.querySelector('#camera');if(!video.videoWidth)return;const auto=counting,token=countdownVersion;let captured;try{captured=await captureStill(video);}catch(err){cancelCountdown();const error=document.querySelector('#camera-error');error.classList.remove('hidden');error.textContent=lang==='fr'?'La caméra a renvoyé une image noire. Gardez la caméra ouverte et réessayez.':err.message;return;}if(state!=='capture'||(auto&&(token!==countdownVersion||!liveReady))){captured.close?.();return;}photo=captured;await measure();};prepareEngine().then(()=>{if(state==='capture')document.querySelector('#capture-info').textContent=t('shutter');}).catch(e=>{if(state==='capture')document.querySelector('#capture-info').textContent=e.message;});
}else if(state==='processing'){
app.innerHTML=`<section class="scan-processing"><div class="processing-hand">${processingIcon()}</div><h1>${t('calculating')}</h1><p>${t('time')}</p><div class="processing-steps">${t('steps').map((text,i)=>`<div class="processing-step ${i<stage?'done':i===stage?'active':''}"><span>${i<stage?'✓':''}</span>${text}</div>`).join('')}</div></section>`;
}else if(state==='result'){
const result=adjustedResult(results[selected]);app.innerHTML=`<section class="scan-shell"><h1 class="desktop-title">${t('title')}</h1><section class="scan-result"><h1>${t('recommended')}</h1><div class="product-banner"><svg viewBox="0 0 30 30" aria-hidden="true"><path d="m15 2 3 4 5-1 1 5 4 3-3 4 1 5-5 1-3 4-4-3-5 1-1-5-4-3 3-4-1-5 5-1Z"/><path d="M15 9v8m0 4v1"/></svg><span>${t('product')}</span></div><div class="finger-carousel"><button class="finger-arrow prev" id="prev" aria-label="${lang==='fr'?'Doigt précédent':'Previous finger'}">‹</button><div class="finger-icon">${handIcon(selected)}</div><p class="finger-name">${t(result.finger)}</p><button class="finger-arrow next" id="next" aria-label="${lang==='fr'?'Doigt suivant':'Next finger'}">›</button></div><div class="result-measurement">${testAdjustMarkup(result)}<p>${lang==='fr'?'Résultat de votre tableau':'Result from your sizing table'}</p><div class="result-size"><strong>${result.measured===false||result.outOfRange?'—':'US '+result.size}</strong><span class="fit-tag fit-${result.zone}">${t(result.measured===false?'notMeasured':result.outOfRange?'unavailable':result.zone)}</span></div><p class="result-description">${result.measured===false?fingerFailureDescription(result):result.outOfRange?adjustedOutDescription(result):t(result.zone+'Description')}</p><p class="result-circumference">${t(result.measurementSource==='measured'?'measured':'circumference')}: ${result.circumference===null?'—':result.circumference.toFixed(1)+' mm'}</p>${circumferenceCalculation(result)}${tableSizeMarkup(result)}${stabilityNotice(result)}<div class="result-quality"><div class="quality-track"><span style="width:${result.quality}%"></span></div><span>${result.quality}%</span></div><p class="quality-caption">${t('quality')}</p></div>${testTableMarkup(result)}<details class="measurement-correction"><summary>${t('correct')}</summary><p>${t('correctionHelp')}</p><form id="correction-form"><label for="actual-circumference">${t('measured')} (mm)</label><div><input id="actual-circumference" type="number" inputmode="decimal" min="30" max="100" step="0.001" required placeholder="mm"><button type="submit">${t('apply')}</button></div><p id="correction-error" role="alert"></p></form></details><button class="result-repeat" id="repeat">${t('repeat')}</button><p class="scan-estimate-note">${t('estimate')}</p></section></section>`;
if(document.querySelector('#test-percent'))document.querySelector('#test-percent').onchange=e=>{testPercent=Number(e.target.value)||0;render();};
document.querySelector('#correction-form').onsubmit=async e=>{e.preventDefault();const input=document.querySelector('#actual-circumference'),circumference=Number(input.value),finger=result.finger;if(!input.value||!Number.isFinite(circumference)||circumference<30||circumference>100){document.querySelector('#correction-error').textContent=t('correctionError');return;}try{receive(await patch({correction:{finger,circumference}}));}catch(err){document.querySelector('#correction-error').textContent=err.message;}};
for(const [id,delta] of [['prev',-1],['next',1]])document.querySelector('#'+id).onclick=()=>{selected=(selected+delta+4)%4;render();patch({selectedFinger:selected}).catch(()=>{});};document.querySelector('#repeat').onclick=async()=>{await patch({status:'connected',results:null,selectedFinger:0});results=null;selected=0;state=onPhone?'intro':'waiting';render();};
}else if(state==='error'){
app.innerHTML=`<section class="scan-error"><h1>${t('noResult')}</h1><p id="error-message"></p>${button('retry','retry')}${legal()}</section>`;document.querySelector('#error-message').textContent=message;document.querySelector('#retry').onclick=()=>{if(!session){const url=new URL(location.href);url.searchParams.delete('sid');location.href=url.href;return;}state='capture';render();startCamera();};
}else{
app.innerHTML=`<section class="scan-shell"><h1 class="desktop-title">${t('title')}</h1><div class="scan-status"><h1>${t('connected')}</h1><p>${session?.status==='error'?t('phoneError'):session?.status==='reviewing'?t('reviewWaiting'):t('connectedText')}</p></div></section>`;
}
document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>modal(t(b.dataset.policy),`<p>${t(b.dataset.policy==='privacy'?'privacyText':'guideText')}</p>`));
}
function receive(s){if(state==='closed')return;if(s.status==='closed'){session=s;endPhoneSession();return;}session=s;if(s.status==='reviewing'&&state!=='review'){if(!onPhone){state='waiting';render();}return;}if(s.status==='analyzing'&&state==='processing'){stage=s.stage||0;render();}if(s.status==='result'&&s.results){results=s.results;selected=s.selectedFinger;state='result';render();return;}if(onPhone){if(state==='result'&&s.results===null){results=null;state='intro';render();}return;}if(!['intro','capture','processing','review','error'].includes(state)){stage=s.stage||0;state=s.status==='waiting'?'qr':s.status==='analyzing'?'processing':'waiting';render();}}
let sessionPoll=null;
function endPhoneSession(){
 stop();releasePhoto();cancelCountdown();events?.close();clearInterval(sessionPoll);results=null;state='closed';document.querySelector('#policy')?.close();render();
}
async function initialize(){
 app.innerHTML=`<section class="scan-status"><p>${t('loading')}</p></section>`;
 let sid=params.get('sid');
 if(!onPhone){
  let previous=sid;try{previous=previous||sessionStorage.getItem('ring-sizing-desktop-session');}catch{}
  if(previous){const response=await fetch('/api/sessions/'+encodeURIComponent(previous),{method:'DELETE'});if(!response.ok&&response.status!==404)throw new Error('Could not reset the old session. Please refresh again.');}
  sid=null;state='qr';testPercent=0;
 }
 if(sid){const response=await fetch('/api/sessions/'+encodeURIComponent(sid));if(response.ok){session=await response.json();if(session.status==='closed'){endPhoneSession();return;}}else if(onPhone){endPhoneSession();return;}}
 if(!session){
  const response=await fetch('/api/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang})});
  if(!response.ok)throw new Error('Sizing server is unavailable.');session=await response.json();
  const url=new URL(location.href);url.searchParams.set('sid',session.id);history.replaceState(null,'',url);
 }
 if(!onPhone){try{sessionStorage.setItem('ring-sizing-desktop-session',session.id);}catch{}}
 configureSession(session.id);
 if(onPhone&&(!session.results||session.status==='reviewing'))await patch({status:'connected',results:null});
 render();events=new EventSource(`/api/sessions/${session.id}/events`);events.onmessage=e=>receive(JSON.parse(e.data));
 sessionPoll=setInterval(async()=>{if(state==='closed')return;try{const r=await fetch('/api/sessions/'+session.id);if(r.status===404||r.status===410){endPhoneSession();return;}if(r.ok){const next=await r.json();if(next.status!==session.status||next.selectedFinger!==session.selectedFinger||JSON.stringify(next.results)!==JSON.stringify(session.results)||JSON.stringify(next.confirmedSizes)!==JSON.stringify(session.confirmedSizes))receive(next);}}catch{}},4000);
}
window.addEventListener('pageshow',e=>{if(e.persisted&&!onPhone)location.reload();});
async function startCamera(){try{const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:2560},height:{ideal:1920}},audio:false});if(state!=='capture'){next.getTracks().forEach(t=>t.stop());return;}stream=next;const video=document.querySelector('#camera');video.srcObject=next;video.onloadedmetadata=()=>{document.querySelector('#shutter').disabled=false;};}catch{if(state==='capture'){const error=document.querySelector('#camera-error');error.classList.remove('hidden');error.textContent=t('cameraError');}}}
async function visiblePhoto(source,video){const box=video.getBoundingClientRect(),w=source.videoWidth||source.width,h=source.videoHeight||source.height,crop=coverCrop(w,h,box.width,box.height),ratio=Math.min(1,2400/Math.max(crop.width,crop.height)),canvas=document.createElement('canvas');canvas.width=Math.round(crop.width*ratio);canvas.height=Math.round(crop.height*ratio);canvas.getContext('2d').drawImage(source,crop.x,crop.y,crop.width,crop.height,0,0,canvas.width,canvas.height);return freezeFrame(canvas);}
async function captureStill(video){
const track=stream?.getVideoTracks()[0];
if(track&&typeof ImageCapture!=='undefined'){try{const original=await createImageBitmap(await new ImageCapture(track).takePhoto());try{return await visiblePhoto(original,video);}finally{original.close();}}catch{/* Use the live frame if still capture is unsupported. */}}
return visiblePhoto(video,video);
}
setInterval(async()=>{if(state!=='capture'||!stream||checking)return;const video=document.querySelector('#camera');if(!video?.videoWidth)return;checking=true;try{const check=await inspectFrame(video);if(state!=='capture')return;const checks=[check.hand&&check.card&&check.framed!==false&&check.resolutionOK!==false,check.spread,(tilt===null?check.flat:tilt<10)&&check.flat];liveReady=checks.every(Boolean);checks.forEach((ok,i)=>{const el=document.querySelector('#check-'+i);el.classList.toggle('good',ok);el.querySelector('.check-icon').textContent=ok?'✓':'×';});updateLevel();if(!liveReady){if(counting)cancelCountdown();stable=0;}else if(!counting){stable++;if(stable>=3)countdownCapture();}}catch{liveReady=false;if(counting)cancelCountdown();stable=0;}finally{checking=false;}},1000);
window.addEventListener('deviceorientation',e=>{const next=phoneLevel(e.beta,e.gamma,Number(screen.orientation?.angle||window.orientation||0));if(!next)return;level=next;tilt=next.angle;if(state==='capture'){updateLevel();if(tilt>=10&&counting){liveReady=false;cancelCountdown();}const el=document.querySelector('#check-2');el.classList.toggle('good',tilt<10);el.querySelector('.check-icon').textContent=tilt<10?'✓':'×';}});
function releasePhoto(){photo?.close?.();photo=null;}
async function measure(){stop();state='processing';stage=0;render();try{await patch({status:'analyzing'});const measurement=await analyzeHand(photo,s=>{if(state!=='closed'){stage=s;render();}});receive({...session,status:'result',results:measurement.results,selectedFinger:0});}catch(e){if(state==='closed')return;try{const r=await fetch('/api/sessions/'+session.id);if(r.ok&&(await r.json()).status==='closed'){endPhoneSession();return;}}catch{}await patch({status:'error'}).catch(()=>{});showError(e.message);}finally{releasePhoto();}}
window.addEventListener('pagehide',releasePhoto);
function showError(text){if(state==='closed')return;stop();message=text;state='error';render();}
window.addEventListener('pagehide',()=>{stop();events?.close();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(state==='capture'&&!stream)startCamera();});
initialize().catch(e=>showError(e.message));
